// The Fishing view: what Cobscook Bay could feed you, season by season.
//
// Pure functions first (the tests run them in Node), then createFishing(), which wires the
// controls in the browser. Numbers come from data/fishing.js (generated by
// tools/fishing_model.py); words, colors and species notes from data/fishing-notes.js.
//
// Two ways to look at it ("Compare each species"):
//   share  each season as a ring: that season's harvest split by species (relative)
//   own    a calendar: each species as a % of its own best season (independent)
// and three things to measure: number caught, pounds of meat, or calories.

import { SEASONS, SPECIES } from "../data/fishing.js";
import {
  FISH_PAGE, SPECIES_COLORS, OTHER_COLOR, MEASURES, PROFILES, BASIS, METHOD, FISH_NOTES, SEAWEED, FISH_SOURCES,
} from "../data/fishing-notes.js";
import { esc } from "./geo.js";

export const DEFAULT_STATE = { measure: "meat", mode: "share" };
const STORE = "prep-lt-fish";
const PEOPLE_KCAL = 2000; // calories a day per person

// ---------- numbers ----------

export const seasonOfDate = (d = new Date()) => Math.floor(d.getMonth() / 2);

export function valueOf(sp, measure, b) {
  if (measure === "count") return sp.count[b];
  if (measure === "kcal") return sp.kcal[b];
  return sp.meat[b];
}

export function seasonTotal(list, measure, b) {
  return list.reduce((sum, sp) => sum + valueOf(sp, measure, b), 0);
}

// People the season's harvest could feed for its two months.
export function peopleFed(list, b, seasons = SEASONS) {
  return seasonTotal(list, "kcal", b) / (PEOPLE_KCAL * seasons[b].days);
}

// That season's species, biggest first, each with its share of the season's total (0–100).
export function seasonShares(list, measure, b) {
  const total = seasonTotal(list, measure, b);
  return list
    .map((sp) => ({ sp, value: valueOf(sp, measure, b) }))
    .filter((x) => x.value > 0)
    .map((x) => ({ ...x, share: total ? (100 * x.value) / total : 0 }))
    .sort((a, b2) => b2.value - a.value);
}

// A species' six seasons as a % of its own best one (0–100).
export function ownIndex(sp, measure) {
  const vals = [0, 1, 2, 3, 4, 5].map((b) => valueOf(sp, measure, b));
  const max = Math.max(...vals);
  return vals.map((v) => (max ? Math.round((100 * v) / max) : 0));
}

// Ranks seasons best (1) to worst; equal values share a rank; empty seasons get none.
export function seasonRanks(values) {
  const order = [...new Set(values.filter((v) => v > 0))].sort((a, b) => b - a);
  return values.map((v) => (v > 0 ? order.indexOf(v) + 1 : null));
}

// The biggest few species as ring slices, the rest folded into "Other".
export function donutSlices(shares, top = 4) {
  const slices = shares.slice(0, top).map(({ sp, value, share }) => ({
    id: sp.id, name: sp.name, color: SPECIES_COLORS[sp.id] || OTHER_COLOR, value, share,
  }));
  const rest = shares.slice(top);
  if (rest.length) {
    slices.push({
      id: "other", name: `Other (${rest.length})`, color: OTHER_COLOR,
      value: rest.reduce((s, x) => s + x.value, 0), share: rest.reduce((s, x) => s + x.share, 0),
    });
  }
  return slices;
}

// Species ordered for the calendar: by their best season, then by size of that peak.
export function calendarOrder(list, measure) {
  const peakOf = (sp) => {
    const idx = ownIndex(sp, measure);
    const flat = idx.every((v) => v >= 80);
    return flat ? 6 : idx.indexOf(100);
  };
  return [...list].sort((a, b) => peakOf(a) - peakOf(b) || valueOf(b, measure, peakOfSeason(b, measure)) - valueOf(a, measure, peakOfSeason(a, measure)));
}
const peakOfSeason = (sp, measure) => ownIndex(sp, measure).indexOf(100);

// ---------- words for numbers ----------

// Two significant figures, with commas: 21,250 -> 21,000.
export function round2(n) {
  if (!n) return 0;
  if (Math.abs(n) < 100) return Math.round(n);
  const p = 10 ** (Math.floor(Math.log10(Math.abs(n))) - 1);
  return Math.round(n / p) * p;
}
export const commas = (n) => Math.round(n).toLocaleString("en-US");

export function shortNum(n) {
  if (n >= 1e6) return `${(n / 1e6).toFixed(n >= 1e7 ? 0 : 1)}M`;
  if (n >= 1e3) return `${(n / 1e3).toFixed(n >= 1e4 ? 0 : 1)}k`;
  return String(Math.round(n));
}

export function measureText(n, measure) {
  if (measure === "kcal") {
    if (n >= 1e6) return `${(round2(n) / 1e6).toLocaleString("en-US")} million cal`;
    return `${commas(round2(n))} cal`;
  }
  if (measure === "meat") return `${commas(round2(n))} lb`;
  return commas(round2(n));
}

export const pct = (x) => (x > 0 && x < 0.5 ? "<1%" : `${Math.round(x)}%`);

const CENTER_UNIT = { count: "animals", meat: "lb of meat", kcal: "calories" };

export function explainText(state) {
  const m = MEASURES[state.measure].short;
  if (state.mode === "own") {
    return `Each row is one species. Each square is that season as a % of the species' own best season (100 = its best), by ${m}. Darker means more. Tap a season to see it below.`;
  }
  return `Each ring is one season's harvest split by species, by ${m}. The middle shows the season's total. Tap a season to see every species below.`;
}

// ---------- drawing (HTML strings) ----------

function donutSvg(slices, total, measure, label) {
  const r = 44, C = 2 * Math.PI * r;
  let at = 0;
  const arcs = slices.map((s) => {
    const len = (s.share / 100) * C;
    const gap = len > 2 ? 1 : 0;
    const arc = `<circle cx="60" cy="60" r="${r}" fill="none" stroke="${esc(s.color)}" stroke-width="20" stroke-dasharray="${(len - gap).toFixed(2)} ${C.toFixed(2)}" stroke-dashoffset="${(-at).toFixed(2)}" transform="rotate(-90 60 60)"><title>${esc(`${s.name}: ${measureText(s.value, measure)}, ${pct(s.share)}`)}</title></circle>`;
    at += len;
    return arc;
  }).join("");
  return `<svg class="ltf-donut" viewBox="0 0 120 120" role="img" aria-label="${esc(label)}">
      <circle cx="60" cy="60" r="${r}" fill="none" stroke="var(--line)" stroke-width="20" opacity="0.35"/>${arcs}
      <text x="60" y="58" text-anchor="middle" class="ltf-donut-big">${esc(shortNum(total))}</text>
      <text x="60" y="74" text-anchor="middle" class="ltf-donut-small">${esc(CENTER_UNIT[measure])}</text>
    </svg>`;
}

export function drawDonuts(state, season, list = SPECIES, seasons = SEASONS) {
  const cards = seasons.map((s, b) => {
    const shares = seasonShares(list, state.measure, b);
    const total = seasonTotal(list, state.measure, b);
    const slices = donutSlices(shares);
    const label = `${s.long}: ${measureText(total, state.measure)}. ` + slices.map((x) => `${x.name} ${pct(x.share)}`).join(", ");
    const legend = slices.map((x) => `
        <li><span class="ltf-swatch" style="background:${esc(x.color)}"></span><span class="ltf-leg-name">${esc(x.name)}</span><span class="ltf-leg-val">${esc(measureText(x.value, state.measure))} · <b>${esc(pct(x.share))}</b></span></li>`).join("");
    return `
      <article class="ltf-card${b === season ? " is-on" : ""}">
        <h3 class="ltf-card-title"><button type="button" data-season="${b}" aria-pressed="${b === season}">${esc(s.label)}</button></h3>
        ${donutSvg(slices, total, state.measure, label)}
        <p class="ltf-people">Feeds <b>~${esc(commas(round2(peopleFed(list, b, seasons))))}</b> people</p>
        <ol class="ltf-legend">${legend}</ol>
      </article>`;
  }).join("");
  return `<div class="ltf-cards">${cards}</div>`;
}

export function drawCalendar(state, season, list = SPECIES, seasons = SEASONS) {
  const heads = seasons.map((s, b) => `<th scope="col"${b === season ? ' class="is-on"' : ""}><button type="button" data-season="${b}" aria-pressed="${b === season}">${esc(s.label.replace("–", "–​"))}</button></th>`).join("");
  const rows = calendarOrder(list, state.measure).map((sp) => {
    const idx = ownIndex(sp, state.measure);
    const ranks = seasonRanks(idx);
    const flat = idx.every((v) => v === 100);
    const cells = idx.map((v, b) => {
      const tip = v ? `${sp.name}, ${seasons[b].label}: ${v}% of its best season (rank ${ranks[b]} of 6), ${measureText(valueOf(sp, state.measure, b), state.measure)}` : `${sp.name}, ${seasons[b].label}: not around, or too few`;
      const mix = Math.round(8 + v * 0.82);
      const cls = ["ltf-cell", v >= 55 ? "is-dark" : "", b === season ? "is-on" : "", v === 100 && !flat ? "is-best" : ""].filter(Boolean).join(" ");
      return `<td class="${cls}" style="--mix:${v ? mix : 0}%" title="${esc(tip)}">${v ? v : "–"}</td>`;
    }).join("");
    return `<tr><th scope="row"><span class="ltf-swatch" style="background:${esc(SPECIES_COLORS[sp.id] || OTHER_COLOR)}"></span>${esc(sp.name)}</th>${cells}</tr>`;
  }).join("");
  return `
    <div class="table-scroll ltf-cal-wrap">
      <table class="ltf-cal">
        <caption>% of each species' own best season, by ${esc(MEASURES[state.measure].short)}. Outlined = best season. Same all year = no outline.</caption>
        <thead><tr><th scope="col">Species</th>${heads}</tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>`;
}

function profileHtml(sp, b) {
  const p = PROFILES[sp.id] || {};
  const trip = sp.tripMeat[b];
  const rows = [
    ["One trip", trip ? `${trip} lb of meat, about ${commas(round2(trip * sp.kcalPerLb))} calories` : "Not worth a trip this season"],
    ["Best season", p.best], ["Size", p.size], ["Meat yield", p.yield],
    ["Calories per lb of meat", commas(sp.kcalPerLb)], ["Gear", p.gear], ["Rules today", p.rules], ["Notes", p.safety],
    ["How sure", `${sp.basis}: ${BASIS[sp.basis]}`],
  ].filter(([, v]) => v);
  return `<dl class="ltf-profile">${rows.map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join("")}</dl>`;
}

export function drawDetail(state, season, list = SPECIES, seasons = SEASONS) {
  const s = seasons[season];
  const tabs = seasons.map((x, b) => `<button type="button" class="ltf-stab" data-season="${b}" data-local aria-pressed="${b === season}">${esc(x.label)}</button>`).join("");
  const meat = seasonTotal(list, "meat", season);
  const kcal = seasonTotal(list, "kcal", season);
  const people = commas(round2(peopleFed(list, season, seasons)));

  const trips = list
    .filter((sp) => sp.tripMeat[season])
    .map((sp) => ({ sp, meat: sp.tripMeat[season], kcal: sp.tripMeat[season] * sp.kcalPerLb }))
    .sort((a, b) => b.kcal - a.kcal);
  const shore = trips.filter((t) => !t.sp.boat);
  const pick = [...trips.slice(0, 3)];
  if (!pick.some((t) => !t.sp.boat) && shore.length) pick.push(shore[0]);
  const best = pick.map((t) => `
      <li class="ltf-trip">
        <span class="ltf-trip-name"><span class="ltf-swatch" style="background:${esc(SPECIES_COLORS[t.sp.id])}"></span>${esc(t.sp.name)}</span>
        <span class="ltf-trip-num"><b>${esc(String(t.meat))} lb</b> of meat a trip</span>
        <span class="ltf-trip-sub">about ${esc(commas(round2(t.kcal)))} calories${t.sp.boat ? " · needs a boat or the lowest tides" : " · from shore"}</span>
      </li>`).join("");

  const own = state.mode === "own";
  const shares = seasonShares(list, state.measure, season);
  const items = own
    ? shares.map((x) => ({ ...x, idx: ownIndex(x.sp, state.measure)[season] })).sort((a, b) => b.idx - a.idx || b.value - a.value)
    : shares;
  const maxShare = Math.max(...items.map((x) => x.share), 1);
  const bars = items.map((x) => {
    const width = own ? x.idx : (100 * x.share) / maxShare;
    const label = own
      ? `<b>${x.idx}%</b> of its best · ${esc(measureText(x.value, state.measure))}`
      : `${esc(measureText(x.value, state.measure))} · <b>${esc(pct(x.share))}</b>`;
    return `
      <li>
        <details class="ltf-row">
          <summary>
            <span class="ltf-row-name">${esc(x.sp.name)} <span class="ltf-basis ltf-basis-${esc(x.sp.basis)}" title="${esc(BASIS[x.sp.basis])}">${esc(x.sp.basis)}</span></span>
            <span class="ltf-row-bar"><span style="width:${width.toFixed(1)}%;background:${esc(SPECIES_COLORS[x.sp.id] || OTHER_COLOR)}"></span></span>
            <span class="ltf-row-val">${label}</span>
          </summary>
          ${profileHtml(x.sp, season)}
        </details>
      </li>`;
  }).join("");
  const gone = list.filter((sp) => !valueOf(sp, state.measure, season)).map((sp) => sp.name);

  return `
    <div class="ltf-stabs" role="group" aria-label="Season">${tabs}</div>
    <h3 class="sub-title ltf-detail-title">${esc(s.long)}</h3>
    <p class="ltf-detail-lead">About <b>${esc(commas(round2(meat)))} lb</b> of meat and <b>${esc(measureText(kcal, "kcal").replace(" cal", " calories"))}</b>: enough for about <b>${esc(people)} people</b> for these two months.</p>
    <h4 class="ltf-h4">Most food for one trip</h4>
    <ol class="ltf-trips">${best}</ol>
    <h4 class="ltf-h4">${own ? `Every species, by how close to its best season it is (${esc(MEASURES[state.measure].short)})` : `Every species, by share of the season's ${esc(MEASURES[state.measure].short)}`}</h4>
    <p class="ltf-hint">Tap a species for its size, gear, rules and safety notes.</p>
    <ol class="ltf-bars">${bars}</ol>
    ${gone.length ? `<p class="ltf-gone">Not around, or too few to bother with: ${esc(gone.join(", "))}.</p>` : ""}`;
}

// The static page: heading, controls, empty chart and detail areas, notes.
export function renderFishing(page = FISH_PAGE) {
  const seg = (name, options) => options.map(([v, label], i) => `
        <label class="ltm-seg-item"><input type="radio" name="${name}" value="${esc(v)}"${i === 0 ? " checked" : ""}><span>${esc(label)}</span></label>`).join("");
  const measures = Object.entries(MEASURES).map(([k, m]) => [k, m.label]);
  const basis = Object.entries(BASIS).map(([k, v]) => `<li><span class="ltf-basis ltf-basis-${esc(k)}">${esc(k)}</span> ${esc(v)}</li>`).join("");
  return `
    <section class="ltf" aria-labelledby="ltf-heading">
      <h2 id="ltf-heading" class="section-title">${esc(page.heading)}</h2>
      <p class="muted ltf-intro">${esc(page.intro)} <span class="ltf-draft">${esc(page.draft)}</span></p>

      <div class="ltf-controls">
        <div class="ltm-group" role="radiogroup" aria-labelledby="ltf-measure-label">
          <span id="ltf-measure-label" class="ltm-label">Show</span>
          <div class="ltm-seg">${seg("ltf-measure", measures)}</div>
        </div>
        <div class="ltm-group" role="radiogroup" aria-labelledby="ltf-mode-label">
          <span id="ltf-mode-label" class="ltm-label">Compare each species</span>
          <div class="ltm-seg ltf-seg-2">${seg("ltf-mode", [["share", "With the others that season"], ["own", "With its own seasons"]])}</div>
        </div>
      </div>

      <p class="ltf-explain" data-explain aria-live="polite"></p>
      <div class="ltf-chart" data-chart></div>
      <div class="ltf-detail" data-detail></div>

      <details class="ltm-notes" open>
        <summary>Keep in mind</summary>
        <ul>${FISH_NOTES.map((n) => `<li>${esc(n)}</li>`).join("")}</ul>
      </details>
      <details class="ltm-notes">
        <summary>Seaweed (not counted above)</summary>
        <div class="table-scroll"><table class="data ltf-table">
          <thead><tr><th scope="col">Seaweed</th><th scope="col">Best time to pick</th><th scope="col">Use</th></tr></thead>
          <tbody>${SEAWEED.map((r) => `<tr>${r.map((c, i) => (i ? `<td>${esc(c)}</td>` : `<th scope="row">${esc(c)}</th>`)).join("")}</tr>`).join("")}</tbody>
        </table></div>
        <p class="ltf-hint">Cut the fronds and leave the base attached so it grows back. Don't pick near sewage outfalls.</p>
      </details>
      <details class="ltm-notes">
        <summary>How these numbers were made</summary>
        <ul class="ltf-basis-list">${basis}</ul>
        <ol>${METHOD.map((n) => `<li>${esc(n)}</li>`).join("")}</ol>
      </details>
      <details class="ltm-notes">
        <summary>Sources</summary>
        <ul>${FISH_SOURCES.map(([t, u]) => `<li><a href="${esc(u)}" target="_blank" rel="noopener">${esc(t)}</a></li>`).join("")}</ul>
      </details>
    </section>`;
}

// ---------- browser ----------

function readState() {
  try {
    const s = JSON.parse(localStorage.getItem(STORE) || "{}");
    return {
      measure: MEASURES[s.measure] ? s.measure : DEFAULT_STATE.measure,
      mode: s.mode === "own" ? "own" : DEFAULT_STATE.mode,
    };
  } catch { return { ...DEFAULT_STATE }; }
}
function saveState(state) {
  try { localStorage.setItem(STORE, JSON.stringify({ measure: state.measure, mode: state.mode })); } catch { /* private mode */ }
}

export function createFishing(panel) {
  const $ = (sel) => panel.querySelector(sel);
  const state = readState();
  let season = seasonOfDate();
  const chart = $("[data-chart]"), detail = $("[data-detail]"), explain = $("[data-explain]");

  for (const input of panel.querySelectorAll('input[name="ltf-measure"]')) input.checked = input.value === state.measure;
  for (const input of panel.querySelectorAll('input[name="ltf-mode"]')) input.checked = input.value === state.mode;

  function draw() {
    explain.textContent = explainText(state);
    chart.innerHTML = state.mode === "own" ? drawCalendar(state, season) : drawDonuts(state, season);
    const open = new Set([...detail.querySelectorAll("details[open] .ltf-row-name")].map((n) => n.textContent));
    detail.innerHTML = drawDetail(state, season);
    for (const d of detail.querySelectorAll("details")) {
      if (open.has(d.querySelector(".ltf-row-name")?.textContent)) d.open = true;
    }
  }

  function onChange(e) {
    if (e.target.name === "ltf-measure") state.measure = e.target.value;
    else if (e.target.name === "ltf-mode") state.mode = e.target.value;
    else return;
    saveState(state);
    draw();
  }
  function onClick(e) {
    const btn = e.target.closest("[data-season]");
    if (!btn || !panel.contains(btn)) return;
    season = Number(btn.dataset.season);
    draw();
    if (!btn.hasAttribute("data-local")) {
      detail.scrollIntoView({ behavior: "smooth", block: "start" });
    } else {
      detail.querySelector(`[data-season="${season}"]`)?.focus();
    }
  }

  panel.addEventListener("change", onChange);
  panel.addEventListener("click", onClick);
  draw();

  return {
    destroy() {
      panel.removeEventListener("change", onChange);
      panel.removeEventListener("click", onClick);
    },
  };
}
